#include "se/activity_wave.hpp"
#include <algorithm>
#include <unordered_map>
namespace se { WaveResult propagate(CognitiveGraph& g,std::span<const std::uint32_t> seeds,std::uint64_t tick,std::uint32_t cap,double retention,double attenuation){WaveResult out;std::unordered_map<std::uint32_t,double> frontier;for(auto id:seeds){frontier[id]=g.activity[id];out.active.push_back(id);out.energy+=g.activity[id];}for(;!frontier.empty()&&out.steps<cap;++out.steps){std::unordered_map<std::uint32_t,double> incoming;for(auto [s,available]:frontier){double sum=0;g.for_each_outgoing(s,[&](Edge&e,RelationHandle){if(e.type!=RelationType::Inhibitory)sum+=std::max(0.,e.strength*e.confidence);});if(sum)g.for_each_outgoing(s,[&](Edge&e,RelationHandle){if(e.type!=RelationType::Inhibitory){incoming[e.target]+=available*retention*(e.strength*e.confidence)/sum;e.last_used_cognitive_tick=tick;}});}frontier.clear();for(auto [id,e]:incoming)if(std::find(out.active.begin(),out.active.end(),id)==out.active.end()){double received=e*(g.refractory[id]?attenuation:1.);g.activity[id]=std::clamp(g.activity[id]+received,0.,1.);if(g.activity[id]>=g.threshold[id]){frontier[id]=received;out.active.push_back(id);out.energy+=received;g.last_active_cognitive_tick[id]=tick;}}}std::sort(out.active.begin(),out.active.end());return out;} }
